ExtremeValueTheory.ae_tendsto_of_wald.{u_1, u_2, u_3} {Θ : Type u_1} [MetricSpace Θ] {α : Type u_2}
  {mα : MeasurableSpace α} {μ : MeasureTheory.Measure α} {m : Θ → α → ℝ} {G : α → ℝ}
  [CompactSpace Θ] [MeasureTheory.IsProbabilityMeasure μ] {Ω : Type u_3} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} {X : ℕ → Ω → α} (hX : ∀ (i : ℕ), ProbabilityTheory.HasLaw (X i) μ P)
  (hind : ProbabilityTheory.iIndepFun X P) (hcont : ∀ (x : α), Continuous fun θ => m θ x)
  (hmeas : ∀ (θ : Θ), Measurable (m θ)) (hG : MeasureTheory.Integrable G μ)
  (hbound : ∀ (θ : Θ) (x : α), |m θ x| ≤ G x) {θ₀ : Θ}
  (hident : ∀ (θ : Θ), θ ≠ θ₀ → ∫ (x : α), m θ x ∂μ < ∫ (x : α), m θ₀ x ∂μ) :
  ∀ᵐ (ω : Ω) ∂P,
    ∀ (θhat : ℕ → Θ),
      (∀ᶠ (n : ℕ) in Filter.atTop,
          ∑ i ∈ Finset.range n, m θ₀ (X i ω) ≤ ∑ i ∈ Finset.range n, m (θhat n) (X i ω)) →
        Filter.Tendsto θhat Filter.atTop (nhds θ₀)

ExtremeValueTheory.tendstoInDistribution_sampleMean_gpd_zero.{u_1, u_2} {σ : ℝ} {Ω : Type u_1}
  {Ω' : Type u_2} {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {P' : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure P'] {X : ℕ → Ω → ℝ}
  (hX : ∀ (i : ℕ), ProbabilityTheory.HasLaw (X i) (ExtremeValueTheory.gpdMeasure 0 σ) P)
  (hind : ProbabilityTheory.iIndepFun X P) {Z : Ω' → ℝ}
  (hZ : ProbabilityTheory.HasLaw Z (ProbabilityTheory.gaussianReal 0 (σ ^ 2).toNNReal) P') :
  MeasureTheory.TendstoInDistribution
    (fun n ω => √↑n * ((ExtremeValueTheory.sampleMean fun i => X (↑i) ω) - σ)) Filter.atTop Z
    (fun x => P) P'

ExtremeValueTheory.tendstoInDistribution_gumbelScoreVec.{u_1, u_2} {μ σ : ℝ} {Ω : Type u_1}
  {Ω' : Type u_2} {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {P' : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure P'] {X : ℕ → Ω → ℝ} (hσ : 0 < σ)
  (hX :
    ∀ (i : ℕ), ProbabilityTheory.HasLaw (X i) (ExtremeValueTheory.gevLocScaleCDF 0 μ hσ).measure P)
  (hind : ProbabilityTheory.iIndepFun X P) {Z : Ω' → EuclideanSpace ℝ (Fin 2)}
  (hZ :
    ProbabilityTheory.HasLaw Z
      (ProbabilityTheory.multivariateGaussian 0 (ExtremeValueTheory.gumbelFisherInfo σ)) P') :
  MeasureTheory.TendstoInDistribution
    (fun n ω => (√↑n)⁻¹ • ∑ i ∈ Finset.range n, ExtremeValueTheory.gumbelScoreVec μ σ (X i ω))
    Filter.atTop Z (fun x => P) P'
